import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { additionalRecipientSchema, type AdditionalRecipient } from "./additional-recipient.js";
import { addressSchema, type Address } from "./address.js";
import { orderSchema, type Order } from "./order.js";

/**
 * Square Checkout lets merchants accept online payments for supported payment types using a
 * checkout workflow hosted on squareup.com.
 */
export type Checkout = {
  /** ID generated by Square Checkout when a new checkout is requested. */
  id?: string;
  /** The URL that the buyer's browser should be redirected to after the checkout is completed. */
  checkoutPageUrl?: string | null;
  /**
   * If `true`, Square Checkout will collect shipping information on your behalf and store that
   * information with the transaction information in your Square Dashboard.
   *
   * Default: `false`.
   */
  askForShippingAddress?: boolean | null;
  /**
   * The email address to display on the Square Checkout confirmation page and confirmation email
   * that the buyer can use to contact the merchant.
   *
   * If this value is not set, the confirmation page and email will display the primary email
   * address associated with the merchant's Square account.
   *
   * Default: none; only exists if explicitly set.
   */
  merchantSupportEmail?: string | null;
  /**
   * If provided, the buyer's email is pre-populated on the checkout page as an editable text field.
   *
   * Default: none; only exists if explicitly set.
   */
  prePopulateBuyerEmail?: string | null;
  /**
   * Represents a postal address in a country. For more information, see [Working with
   * Addresses](https://developer.squareup.com/docs/build-basics/working-with-addresses).
   */
  prePopulateShippingAddress?: Address;
  /**
   * The URL to redirect to after checkout is completed with `checkoutId`, Square's `orderId`,
   * `transactionId`, and `referenceId` appended as URL parameters. For example, if the provided
   * redirect_url is `http://www.example.com/order-complete`, a successful transaction redirects the
   * customer to:
   *
   * <pre><code>http://www.example.com/order-complete?checkoutId=xxxxxx&amp;orderId=xxxxxx&amp;referenceId=xxxxxx&amp;transactionId=xxxxxx</code></pre>
   *
   * If you do not provide a redirect URL, Square Checkout will display an order confirmation page
   * on your behalf; however Square strongly recommends that you provide a redirect URL so you can
   * verify the transaction results and finalize the order through your existing/normal confirmation
   * workflow.
   */
  redirectUrl?: string | null;
  /**
   * Contains all information related to a single order to process with Square, including line items
   * that specify the products to purchase. `Order` objects also include information about any
   * associated tenders, refunds, and returns.
   *
   * All Connect V2 Transactions have all been converted to Orders including all associated
   * itemization data.
   */
  order?: Order;
  /** The time when the checkout was created, in RFC 3339 format. */
  createdAt?: string;
  /**
   * Additional recipients (other than the merchant) receiving a portion of this checkout. For
   * example, fees assessed on the purchase by a third party integration.
   */
  additionalRecipients?: AdditionalRecipient[] | null;
};

export const checkoutSchema: Schema<Checkout> = s.object<Checkout>({
  id: s.optional(s.string()),
  checkoutPageUrl: s.optionalNullable(s.string()),
  askForShippingAddress: s.optionalNullable(s.boolean()),
  merchantSupportEmail: s.optionalNullable(s.string()),
  prePopulateBuyerEmail: s.optionalNullable(s.string()),
  prePopulateShippingAddress: s.optional(s.lazy(() => addressSchema)),
  redirectUrl: s.optionalNullable(s.string()),
  order: s.optional(s.lazy(() => orderSchema)),
  createdAt: s.optional(s.string()),
  additionalRecipients: s.optionalNullable(s.array(s.lazy(() => additionalRecipientSchema))),
  _keysMap: {
    checkoutPageUrl: "checkout_page_url",
    askForShippingAddress: "ask_for_shipping_address",
    merchantSupportEmail: "merchant_support_email",
    prePopulateBuyerEmail: "pre_populate_buyer_email",
    prePopulateShippingAddress: "pre_populate_shipping_address",
    redirectUrl: "redirect_url",
    createdAt: "created_at",
    additionalRecipients: "additional_recipients",
  },
});
